    '暂不支持关注该类型的对象',
    'Following this type of subject is not supported',
    400,
    'surface',
    'inlineCard',
    0,
    '',
  );

  final String code;
  final String defaultMessageZh;
  final String defaultMessageEn;
  final int httpStatus;

  final String recoveryAction;
  final String disruptionLevel;
  final int recoveryAfterSeconds;
  final String l10nKey;

  const UserErrorCode(
    this.code,
    this.defaultMessageZh,
    this.defaultMessageEn,
    this.httpStatus,
    this.recoveryAction,
    this.disruptionLevel,
    this.recoveryAfterSeconds,
    this.l10nKey,
  );

  String get defaultMessage => defaultMessageZh;

  String messageForLocale(String locale) =>
      locale.toLowerCase().startsWith('en')
      ? defaultMessageEn
      : defaultMessageZh;

  static UserErrorCode? fromCode(String code) {
    for (final e in values) {
      if (e.code == code) return e;
    }
    return null;
  }
}
